import type { Metadata } from "next";
import ReviewPage from "@/components/review-consultant/page";
import { apiv3Get } from "@/lib/apiv3";

export const dynamic = "force-static";
export const metadata: Metadata = {
  title: "Review Consultant - TravelShop Booking",
  description: "",
  alternates: {
    canonical: "https://travelshopbooking.com/review-consultant",
  },
};

async function getLocations() {
  if (!process.env.NEXT_PUBLIC_APIV3_URL) {
    return [];
  }

  try {
    const res = await apiv3Get("/countries", { cache: "force-cache" });

    if (!res.ok) return [];

    const json = await res.json();
    return json.data ?? [];
  } catch {
    return [];
  }
}

export default async function ReviewConsultant() {
  const locations = await getLocations();

  return <ReviewPage locations={locations} />;
}
